const KEY='digimax-v2-projects';
function proposalSource(study:any){
  const refs=Array.isArray(study?.referenceSearch?.qualified)?study.referenceSearch.qualified:[];
  const geminiUnavailable=study?.status==='ai-unavailable'||study?._requestError;
  if(refs.length){
    const names=refs.slice(0,3).map((r:any)=>`${r.projectId||'referência'} (${Number(r.compatibility||0).toLocaleString('pt-BR',{maximumFractionDigits:1})}%)`).join(' · ');
    return geminiUnavailable
      ? {kind:'catalog',title:'Gerada com geometryBrief da planilha · Gemini indisponível',detail:`Compatibilidade: ${names}. A Opção A usa a geometria cotada da imagem (lote 20 × 10 m, casa 14 × 8,50 m, recuos e jardim), sem adaptação do Gemini.`}
      : {kind:'catalog',title:'Compatibilizada com planilha Google + Gemini',detail:`Referências usadas: ${names}`};
  }
  if(study?.referenceSearch?.configured){
    return {kind:'ai',title:'Gerada somente com IA',detail:`Nenhuma referência da planilha atingiu ${study.referenceSearch.minimumCompatibility||90}% de compatibilidade.`};
  }
  if(geminiUnavailable) return {kind:'ai',title:'IA indisponível · proposta local',detail:'O Gemini não respondeu e nenhuma referência da planilha foi aplicada.'};
  return {kind:'ai',title:'Gerada somente com IA',detail:'A proposta não recebeu uma referência da planilha nesta geração.'};
}
